// SwaggerUpload.jsx
import React, { useState } from 'react';
import './U.css';

const SwaggerUpload = () => {
  const [uploadedFile, setUploadedFile] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);

  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    handleFile(file);
  };

  const handleFileInput = (e) => {
    const file = e.target.files[0];
    handleFile(file);
  };

  const handleFile = (file) => {
    setUploadedFile(file);
    // Simulate upload progress
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      setUploadProgress(progress);
      if (progress >= 100) clearInterval(interval);
    }, 200);
  };

  return (
    <div className="swagger-container">
      <div className="swagger-header">
        <h2 className="swagger-title">Please Upload your Swagger Document</h2>
        <p className="swagger-subtitle">
          Upload your Swagger YAML file (optional) and/or enter a custom prompt
        </p>
      </div>

      <div
        className="upload-area"
        onDragOver={(e) => e.preventDefault()}
        onDrop={handleDrop}
      >
        <div className="upload-icon-container">
          <svg
            className="upload-icon"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
            <polyline points="17 8 12 3 7 8" />
            <line x1="12" y1="3" x2="12" y2="15" />
          </svg>
        </div>
        <p className="upload-text">Select a file or drag and drop here</p>
        <p className="upload-subtext">
          Upload swagger docs size no more than 200 MB
        </p>
        <label>
          <button className="browse-button">Browse files</button>
          <input
            type="file"
            className="hidden"
            onChange={handleFileInput}
            accept=".yaml,.yml,.json"
          />
        </label>
      </div>

      {uploadedFile && (
        <div className="file-progress">
          <div className="file-info">
            <svg
              className="file-icon"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
            >
              <path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <span className="file-name">Test case-1</span>
            <span className="file-size">200 KB</span>
          </div>
          <div className="progress-bar-container">
            <div
              className="progress-bar"
              style={{ width: `${uploadProgress}%` }}
            />
          </div>
          <div className="progress-text">{uploadProgress}%</div>
        </div>
      )}
    </div>
  );
};

export default SwaggerUpload;
